layers.vertex:
attribute vec3 aO; attribute float aT; attribute vec4 aP; uniform float uTime; varying vec2 vL; varying float vU, vLy, vEdge; varying vec3 vW;
    void main(){ float u = uTime - aT; if (u < 0. || u > 7.5){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float S = 7.2; vec3 W = aO + vec3(position.x*S, 6.55 + aP.x*.45, -position.y*S);
      vL = position.xy*S; vU = u; vLy = aP.x; vW = W;
      vEdge = abs(normalize(cameraPosition - W).y);                              // 0 = seen edge-on
      gl_Position = projectionMatrix*viewMatrix*vec4(W, 1.); }

layers.fragment:
uniform float uTime; uniform vec3 uIceC, uOrange; uniform vec4 uStrike; varying vec2 vL; varying float vU, vLy, vEdge; varying vec3 vW;
    float h(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5); }
    float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
      return mix(mix(h(i), h(i + vec2(1., 0.)), f.x), mix(h(i + vec2(0., 1.)), h(i + vec2(1., 1.)), f.x), f.y); }
    float fbm(vec2 p){ return vn(p)*.55 + vn(p*2.1 + 3.1)*.3 + vn(p*4.3 + 7.7)*.15; }
    void main(){
      float r = length(vL), g = 1. - pow(1. - clamp(vU/.8, 0., 1.), 3.), R = 6.6*(.4 + .6*g);
      float a = uTime*.06*(vLy*2. - 1.), c = cos(a), s = sin(a); vec2 q = mat2(c, -s, s, c)*vL*.32 + vLy*5.3;
      vec2 w = vec2(fbm(q + uTime*.05), fbm(q - uTime*.04 + 4.2));                 // domain warp: billowy, churning
      float n = fbm(q + w*1.4);
      float mask = smoothstep(R, R*.55, r + (n - .5)*2.2);                           // ragged edge
      float dens = smoothstep(.32, .72, n)*mask*smoothstep(.05, .35, vEdge);
      dens *= smoothstep(0., .6, vU)*(1. - smoothstep(6.3, 7.4, vU));
      vec3 base = mix(vec3(.012, .015, .025), vec3(.06, .075, .12), n*n)*(vLy > .5 ? 1.15 : 1.);
      float sd = distance(vW.xz, uStrike.xz), st = uTime - uStrike.w;
      float lit = exp(-sd*sd*.16)*exp(-max(st, 0.)*9.)*step(0., st)*2.4;
      vec3 col = base + mix(uIceC, uOrange, .6)*lit*(.3 + .7*n);
      float al = dens*.7;
      if (al < .004) discard;
      gl_FragColor = vec4(col*al, al);
    }
